'use strict';

// Add-in Id rules: one environment = one add-in identity, generated once (tools/New-NoFridayMailEnvironment.ps1),
// stable across redeployments, unique across environments, never generated by the deploy script.
const test = require('node:test');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const envConfig = require('../package/tools/env-config');

const repo = path.join(__dirname, '..');
const root = path.join(repo, 'package'); // the product
const newScript = path.join(root, 'tools', 'New-NoFridayMailEnvironment.ps1');
const deployScript = path.join(root, 'tools', 'Deploy-NoFridayMail.ps1');
const newText = fs.readFileSync(newScript, 'utf8');
const deployText = fs.readFileSync(deployScript, 'utf8');
const FIXTURES = path.join(repo, 'tests', 'fixtures', 'environments');
const GUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const TEMPLATE_ID = '11111111-2222-4333-8444-555555555555';

const pwshProbe = spawnSync('pwsh', ['-NoProfile', '-Command', '$PSVersionTable.PSVersion.Major'], { encoding: 'utf8' });
const skipPwsh = !(pwshProbe.status === 0 && Number(pwshProbe.stdout.trim()) >= 7) && 'PowerShell 7 not available';

const tempDir = () => fs.mkdtempSync(path.join(os.tmpdir(), 'nfm-newenv-'));
const clean = (text) => text.replace(/\x1b\[[0-9;]*m/g, '').replace(/[^\x20-\x7e\n]+/g, ' ');
const flat = (text) => clean(text).replace(/[\s|]+/g, ' ');
const withFixtures = () => Object.assign({}, process.env, { NFM_ENVIRONMENTS_DIR: FIXTURES });

function runNew(args, env) {
  return spawnSync('pwsh', ['-NoProfile', '-File', newScript, ...args], { encoding: 'utf8', env: env || withFixtures(), timeout: 120000 });
}
const readJson = (file) => JSON.parse(fs.readFileSync(file, 'utf8'));

test('new environment script: house format (requires 7.4, ASCII, help, three stages, uses [guid]::NewGuid())', () => {
  assert.match(newText, /^#Requires -Version 7\.4/);
  assert.doesNotMatch(newText, /[^\x00-\x7f]/, 'ASCII only (the script is signed later)');
  assert.match(newText, /\.SYNOPSIS\s+NoFridayMail - /);
  assert.ok((newText.match(/^\.EXAMPLE/gm) || []).length >= 4, 'at least 4 examples');
  for (const stage of ['1. CHECK', '2. GENERATE', '3. WRITE']) assert.ok(newText.includes(stage), stage);
  for (const name of ['Name', 'DisplayName', 'ResourceGroup', 'StaticWebAppName', 'Location', 'SubscriptionId', 'BlockedDays', 'Path', 'AddinId', 'Force']) {
    assert.match(newText, new RegExp(`\\.PARAMETER ${name}\\r?\\n`), `help for -${name}`);
  }
  assert.match(newText, /\[guid\]::NewGuid\(\)/);
  assert.match(newText, /\[string\]\$Location = 'westeurope'/);
  assert.match(newText, /\[int\[\]\]\$BlockedDays = @\(5\)/);
  assert.match(newText, /SupportsShouldProcess/);
});

test('deploy script never generates an add-in Id: [guid]::NewGuid() only appears inside messages', () => {
  const lines = deployText.split(/\r?\n/).filter((l) => /NewGuid|New-Guid\b(?!\))/.test(l));
  assert.ok(lines.length >= 1, 'the fix is explained to the operator');
  for (const line of lines) assert.match(line, /["']/, `only inside a message or help: ${line.trim()}`);
  assert.doesNotMatch(deployText, /\$[A-Za-z]+\s*=\s*\[guid\]::NewGuid|\$[A-Za-z]+\s*=\s*New-Guid/);
});

test('template Id lists agree: env-config, deploy script and new environment script', () => {
  const list = (source) => (/\$placeholderIds = @\(([^)]*)\)/.exec(source) || [])[1].split(',').map((s) => s.trim().replace(/'/g, '')).sort();
  assert.deepEqual(list(deployText), envConfig.PLACEHOLDER_ADDIN_IDS.slice().sort());
  assert.deepEqual(list(newText), envConfig.PLACEHOLDER_ADDIN_IDS.slice().sort());
  assert.ok(envConfig.PLACEHOLDER_ADDIN_IDS.includes(TEMPLATE_ID));
});

test('add-in Id: the template example.json is a placeholder; prod.json is not', () => {
  const example = readJson(path.join(root, 'deploy', 'environments', 'example.json'));
  const prod = readJson(path.join(root, 'deploy', 'environments', 'prod.json'));
  assert.equal(example.addinId, TEMPLATE_ID);
  assert.ok(!envConfig.PLACEHOLDER_ADDIN_IDS.includes(prod.addinId.toLowerCase()));
  assert.notEqual(example.addinId, prod.addinId);
});

test('add-in Id: deployErrors refuses a template Id with the exact fix, accepts a real one', () => {
  const base = envConfig.loadEnvironment ? JSON.parse(fs.readFileSync(path.join(FIXTURES, 'base.json'), 'utf8')) : null;
  for (const id of envConfig.PLACEHOLDER_ADDIN_IDS) {
    const errors = envConfig.deployErrors(Object.assign({}, base, { addinId: id.toUpperCase() }));
    assert.equal(errors.length, 1, id);
    assert.match(errors[0], /is a placeholder/);
    assert.match(errors[0], /New-NoFridayMailEnvironment\.ps1 -Name <name>/);
    assert.match(errors[0], /\[guid\]::NewGuid\(\)/);
    assert.match(errors[0], /second add-in for every user/);
  }
  assert.deepEqual(envConfig.deployErrors(Object.assign({}, base, { addinId: crypto.randomUUID() })), []);
});

test('add-in Id: an Id shared by two environments is reported with both names and the rule', () => {
  const dir = tempDir();
  try {
    const base = fs.readFileSync(path.join(FIXTURES, 'base.json'), 'utf8');
    const id = crypto.randomUUID();
    for (const name of ['first', 'second']) {
      fs.writeFileSync(path.join(dir, `${name}.json`), base.replace('"name": "base"', `"name": "${name}"`).replace(/"addinId": "[^"]+"/, `"addinId": "${id}"`));
    }
    const previous = process.env.NFM_ENVIRONMENTS_DIR;
    process.env.NFM_ENVIRONMENTS_DIR = dir;
    try {
      assert.deepEqual(envConfig.findAddinIdClashes(id.toUpperCase(), 'first'), ['second']);
      assert.throws(() => envConfig.loadEnvironment('first'), /already used by "second"[\s\S]*never share an add-in Id[\s\S]*Never change the Id/);
      assert.match(envConfig.validateAll().errors.join('|'), /addinId is the same as the one of "first"/);
    } finally {
      if (previous === undefined) delete process.env.NFM_ENVIRONMENTS_DIR;
      else process.env.NFM_ENVIRONMENTS_DIR = previous;
    }
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

test('env-config --stdin validates a candidate without any file', () => {
  const run = (candidate, name) => spawnSync(process.execPath, [path.join(root, 'tools', 'env-config.js'), name, '--stdin'], { encoding: 'utf8', input: JSON.stringify(candidate), env: withFixtures() });
  const base = readJson(path.join(FIXTURES, 'base.json'));
  const fresh = Object.assign({}, base, { name: 'candidate', addinId: crypto.randomUUID() });
  const ok = run(fresh, 'candidate');
  assert.equal(ok.status, 0, ok.stderr);
  assert.match(ok.stdout, /Environment "candidate" is valid/);
  const duplicate = run(Object.assign({}, fresh, { addinId: base.addinId }), 'candidate');
  assert.equal(duplicate.status, 1);
  assert.match(duplicate.stderr, /already used by "base"/);
  const template = run(Object.assign({}, fresh, { addinId: TEMPLATE_ID }), 'candidate');
  assert.equal(template.status, 1);
  assert.match(template.stderr, /is a placeholder/);
  const wrongName = run(fresh, 'other');
  assert.equal(wrongName.status, 1);
  assert.match(wrongName.stderr, /must equal the file name/);
});

test('new environment script (pwsh): generates a valid unique Id, stable on a second run, nothing written by -WhatIf', { skip: skipPwsh, timeout: 240000 }, () => {
  const dir = tempDir();
  try {
    const dry = runNew(['-Name', 'gen', '-Path', dir, '-WhatIf']);
    assert.equal(dry.status, 0, dry.stdout + dry.stderr);
    assert.deepEqual(fs.readdirSync(dir), [], '-WhatIf writes nothing');
    assert.match(clean(dry.stdout), /simulation finished: nothing was written/);

    const first = runNew(['-Name', 'gen', '-Path', dir]);
    assert.equal(first.status, 0, first.stdout + first.stderr);
    const file = path.join(dir, 'gen.json');
    const created = readJson(file);
    assert.match(created.addinId, GUID);
    assert.ok(!envConfig.PLACEHOLDER_ADDIN_IDS.includes(created.addinId));
    for (const name of fs.readdirSync(FIXTURES)) assert.notEqual(readJson(path.join(FIXTURES, name)).addinId, created.addinId);
    assert.equal(created.name, 'gen');
    assert.equal(created.version, '1.0.0.0');
    assert.deepEqual(created.rules.blockedDays, [5]);
    assert.equal(created.azure.location, 'westeurope');
    assert.equal('subscriptionId' in created.azure, false);
    assert.match(clean(first.stdout), /Deploy-NoFridayMail\.ps1 -Environment gen -WhatIf/);
    assert.equal(envConfig.validateEnvironment(created, 'gen').length, 0);

    const before = fs.readFileSync(file, 'utf8');
    const again = runNew(['-Name', 'gen', '-Path', dir]);
    assert.equal(again.status, 1);
    assert.match(flat(again.stdout + again.stderr), /already exists/);
    assert.equal(fs.readFileSync(file, 'utf8'), before, 'the file, and its Id, are untouched');

    const forced = runNew(['-Name', 'gen', '-Path', dir, '-Force', '-DisplayName', 'NoFridayMail (Renamed)']);
    assert.equal(forced.status, 0, forced.stdout + forced.stderr);
    const rewritten = readJson(file);
    assert.equal(rewritten.addinId, created.addinId, '-Force keeps the Id');
    assert.equal(rewritten.displayName, 'NoFridayMail (Renamed)');

    const other = tempDir();
    try {
      assert.equal(runNew(['-Name', 'second', '-Path', other]).status, 0);
      assert.notEqual(readJson(path.join(other, 'second.json')).addinId, created.addinId, 'two environments, two Ids');
    } finally {
      fs.rmSync(other, { recursive: true, force: true });
    }
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

test('new environment script (pwsh): refuses an Id used by a known environment, a template Id and the name example', { skip: skipPwsh, timeout: 240000 }, () => {
  const dir = tempDir();
  try {
    const used = readJson(path.join(FIXTURES, 'base.json')).addinId;
    const duplicate = runNew(['-Name', 'dup', '-Path', dir, '-AddinId', used]);
    assert.equal(duplicate.status, 1);
    assert.match(flat(duplicate.stdout + duplicate.stderr), /already used by the environment 'base'/);
    const template = runNew(['-Name', 'dup', '-Path', dir, '-AddinId', TEMPLATE_ID]);
    assert.equal(template.status, 1);
    assert.match(flat(template.stdout + template.stderr), /template value/);
    const example = runNew(['-Name', 'example', '-Path', dir]);
    assert.equal(example.status, 1);
    assert.deepEqual(fs.readdirSync(dir), [], 'nothing written on refusal');
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

test('deploy script (pwsh): stops on a template add-in Id and on a duplicated one, with the fix', { skip: skipPwsh, timeout: 240000 }, () => {
  const dir = tempDir();
  try {
    const base = fs.readFileSync(path.join(FIXTURES, 'base.json'), 'utf8');
    const write = (name, id) => fs.writeFileSync(path.join(dir, `${name}.json`), base.replace('"name": "base"', `"name": "${name}"`).replace(/"addinId": "[^"]+"/, `"addinId": "${id}"`));
    const shared = crypto.randomUUID();
    write('tpl', TEMPLATE_ID);
    write('twin-a', shared);
    write('twin-b', shared);
    const deploy = (name) => spawnSync('pwsh', ['-NoProfile', '-File', deployScript, '-Environment', name, '-WhatIf', '-SkipInfra'], { encoding: 'utf8', env: Object.assign({}, process.env, { NFM_ENVIRONMENTS_DIR: dir }), timeout: 120000 });

    const tpl = deploy('tpl');
    assert.equal(tpl.status, 1);
    const tplText = flat(tpl.stdout + tpl.stderr);
    assert.match(tplText, /ERROR: The add-in Id of environment 'tpl' is a template value/);
    assert.match(tplText, /New-NoFridayMailEnvironment\.ps1 -Name <name>/);
    assert.match(tplText, /\[guid\]::NewGuid\(\)/);
    assert.match(tplText, /never generates the Id at deployment time/);
    assert.doesNotMatch(tplText, /2\/6/, 'stops before any other stage');

    const twin = deploy('twin-a');
    assert.equal(twin.status, 1);
    const twinText = flat(twin.stdout + twin.stderr);
    assert.match(twinText, /already used by "twin-b"/);
    assert.match(twinText, /never share an add-in Id/);
    assert.doesNotMatch(twinText, /2\/6/);
    assert.equal(fs.readFileSync(path.join(dir, 'tpl.json'), 'utf8').includes(TEMPLATE_ID), true, 'the environment file is never rewritten by the deploy script');
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});
